import { execFile } from 'node:child_process';
import { readFile } from 'node:fs/promises';
import { resolve } from 'node:path';
import { promisify } from 'node:util';

// Emoji and other pictographic characters are not allowed in code, comments, logs, error
// messages, UI text, documentation or commit messages. Post content generated by the AI is data,
// not repository content, and never lives in these files. Tests that need emoji write them as
// escape sequences ('\u{1F600}'), never as literal characters.
//
// Usage:
//   tsx tools/check-no-emoji.ts                    every text file that Git tracks
//   tsx tools/check-no-emoji.ts --commits A..B     the messages of the commits in a range
//
// Only tracked files are scanned, so generated and ignored output (node_modules, dist, the Prisma
// client) is never part of the check. Every tracked text file counts, whatever its extension
// (compose.yaml, .sql, .prisma, Dockerfiles, ...). Files containing a NUL byte are binary and skipped.
const PICTOGRAPHIC = /\p{Extended_Pictographic}/gu;

// Extended_Pictographic also matches these three signs. They are allowed for legal texts.
const ALLOWED = new Set(['©', '®', '™']);

const execFileAsync = promisify(execFile);

function findPictographs(line: string): string[] {
  return [...line.matchAll(PICTOGRAPHIC)].map((match) => match[0]).filter((char) => !ALLOWED.has(char));
}

function codePoints(chars: string[]): string {
  return [...new Set(chars)]
    .map((char) => `U+${(char.codePointAt(0) ?? 0).toString(16).toUpperCase().padStart(4, '0')}`)
    .join(', ');
}

async function git(root: string, args: string[]): Promise<string> {
  const { stdout } = await execFileAsync('git', args, { cwd: root, maxBuffer: 64 * 1024 * 1024 });
  return stdout;
}

async function scanTrackedFiles(root: string): Promise<string[]> {
  const findings: string[] = [];
  const paths = (await git(root, ['ls-files', '-z'])).split('\0').filter((path) => path.length > 0);

  for (const path of paths) {
    const content = await readFile(resolve(root, path));
    if (content.includes(0)) {
      continue;
    }
    content
      .toString('utf8')
      .split('\n')
      .forEach((line, index) => {
        const found = findPictographs(line);
        if (found.length > 0) {
          findings.push(`${path}:${String(index + 1)} (${codePoints(found)})`);
        }
      });
  }
  return findings;
}

async function scanCommitMessages(root: string, range: string): Promise<string[]> {
  const findings: string[] = [];
  // One record per commit: hash, NUL, full message, record separator.
  const log = await git(root, ['log', '--format=%H%x00%B%x1e', range]);

  for (const record of log.split('\x1e')) {
    const [hash, message] = record.trim().split('\0');
    if (!hash || message === undefined) {
      continue;
    }
    const found = findPictographs(message);
    if (found.length > 0) {
      findings.push(`commit ${hash.slice(0, 12)} (${codePoints(found)})`);
    }
  }
  return findings;
}

async function main(): Promise<void> {
  const root = resolve(process.cwd());
  const args = process.argv.slice(2);
  const commitsIndex = args.indexOf('--commits');

  let findings: string[];
  if (commitsIndex === -1) {
    findings = await scanTrackedFiles(root);
  } else {
    const range = args[commitsIndex + 1];
    if (!range) {
      throw new Error('--commits needs a revision range, for example origin/main..HEAD');
    }
    findings = await scanCommitMessages(root, range);
  }

  if (findings.length > 0) {
    process.stdout.write(`Emoji found in ${String(findings.length)} location(s):\n${findings.join('\n')}\n`);
    process.exitCode = 1;
    return;
  }
  process.stdout.write('No emoji found.\n');
}

main().catch((error: unknown) => {
  const message = error instanceof Error ? error.message : 'unknown error';
  process.stderr.write(`${message}\n`);
  process.exitCode = 1;
});
